import json

# Test input
grid = [
    [2, 2, 4, 2, 2, 3, 2, 4, 2, 2, 2],
    [2, 2, 2, 2, 2, 3, 2, 2, 2, 2, 2],
    [2, 2, 2, 2, 2, 3, 2, 2, 2, 2, 2],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [2, 4, 2, 2, 2, 3, 2, 2, 2, 2, 2],
    [2, 2, 2, 2, 2, 3, 2, 2, 2, 4, 2],
    [2, 4, 2, 2, 2, 3, 2, 2, 2, 4, 2],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [4, 2, 2, 2, 2, 3, 2, 2, 2, 2, 2],
    [2, 2, 2, 2, 4, 3, 2, 2, 2, 2, 2],
    [2, 2, 2, 2, 2, 3, 2, 2, 2, 2, 2],
]

h, w = 11, 11

# Find line positions
horz_lines = [i for i in range(1, h-1) if all(grid[i][j] == 3 for j in range(w))]
vert_lines = [i for i in range(1, w-1) if all(grid[j][i] == 3 for j in range(h))]
print("Horz:", horz_lines, "Vert:", vert_lines)

# Define regions
section_rows = len(horz_lines) + 1
section_cols = len(vert_lines) + 1
print(f"Sections: {section_rows} rows × {section_cols} cols = {section_rows * section_cols} total")

# Which section has the most 3s in it?
def which_section(row, col):
    # row/col determine the section (0-indexed)
    # Find which interval row lies in
    if row <= horz_lines[0]:
        r = 0
    elif row <= horz_lines[-1]:
        for i, hl in enumerate(horz_lines):
            if row > hl and (i+1) < len(horz_lines):
                r = i + 1
                break
    else:
        r = len(horz_lines)

    # For cols
    if col <= vert_lines[0]:
        c = 0
    elif col <= vert_lines[-1]:
        for i, vl in enumerate(vert_lines):
            if col > vl and (i+1) < len(vert_lines):
                c = i + 1
                break
    else:
        c = len(vert_lines)

    return r, c

# Count 3s in each section
for i in range(section_rows):
    for j in range(section_cols):
        cnt = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 3:
                    sr, sc = which_section(r, c)
                    if sr == i and sc == j:
                        cnt += 1
        print(f"Section ({i},{j}): {cnt} 3s")

